@paineis_bp.post("/admin/usuarios/novo")
@login_required
@limiter.limit("10 per minute", methods=["POST"])
@requer_permissao("ADMIN_TUDO")
def admin_usuarios_novo_post():
    perfis = db.session.query(DimPerfilUsuario).order_by(DimPerfilUsuario.NomePerfil.asc()).all()

    form_usuario = FormUsuarioNovo()
    form_usuario.id_perfil.choices = [
        (p.IDDimPerfilUsuario, p.NomePerfil or f"Perfil #{p.IDDimPerfilUsuario}")
        for p in perfis
    ]

    # Limpa o email antes do validate_on_submit para remover espaços invisíveis.
    form_usuario.email.data = _limpar_email(form_usuario.email.data)

    if not form_usuario.validate_on_submit():
        flash("Revise os campos do formulário.", "danger")
        return render_template(
            "euromidia/usuarios_form.html",
            modo="novo",
            usuario=None,
            perfis=perfis,
            permissoes_todas=[],
            extras=[],
            form_usuario=form_usuario,
            form_senha=None,
            form_perm_extra=None,
            remover_forms={},
        )

    nome = (form_usuario.nome.data or "").strip()
    email = _limpar_email(form_usuario.email.data)
    senha = form_usuario.senha.data or ""
    id_perfil_int = int(form_usuario.id_perfil.data)
    ativo = (form_usuario.ativo.data or "1").strip()

    existe = db.session.query(DimUsuarios).filter(func.lower(DimUsuarios.Email) == email.lower()).first()
    if existe:
        flash("Já existe usuário com esse email.", "danger")
        return render_template(
            "euromidia/usuarios_form.html",
            modo="novo",
            usuario=None,
            perfis=perfis,
            permissoes_todas=[],
            extras=[],
            form_usuario=form_usuario,
            form_senha=None,
            form_perm_extra=None,
            remover_forms={},
        )

    novo = DimUsuarios(
        IDDimPerfilUsuario=id_perfil_int,
        NomeUsuario=nome or None,
        Email=email,
        HashSenha=_senha_hash(senha),
        BitAtivo=True if ativo == "1" else False,
        CreatedAt=datetime.now(),
        UpdateAt=datetime.now(),
        UltimoLogin=None,
    )

    try:
        db.session.add(novo)
        db.session.flush()

        if _perfil_usuario_eh_admin(id_perfil_int):
            _aplicar_acesso_total_usuario_admin(
                id_usuario=int(novo.IDDimUsuarios),
                id_usuario_executor=_id_usuario_executor_atual(),
            )

        db.session.commit()

    except Exception as erro:
        db.session.rollback()
        current_app.logger.exception("Erro ao criar usuário e aplicar permissões administrativas.")
        flash(f"Erro ao criar usuário: {str(erro)}", "danger")
        return render_template(
            "euromidia/usuarios_form.html",
            modo="novo",
            usuario=None,
            perfis=perfis,
            permissoes_todas=[],
            extras=[],
            form_usuario=form_usuario,
            form_senha=None,
            form_perm_extra=None,
            remover_forms={},
        )

    flash("Usuário criado com sucesso.", "success")
    return redirect(url_for("Paineis.admin_usuarios_editar_form", id_usuario=novo.IDDimUsuarios))







