def _deduplicar_textos_preservando_ordem(valores):
    saida = []
    vistos = set()

    for valor in (valores or []):
        texto = str(valor or "").strip()
        if not texto:
            continue

        chave = texto.casefold()
        if chave in vistos:
            continue

        vistos.add(chave)
        saida.append(texto)

    return saida


def _ordenar_classificacao_macro(valores):
    ordem = {
        "Muito Favorável": 1,
        "Favorável": 2,
        "Neutro": 3,
        "Desfavorável": 4,
        "Muito Desfavorável": 5,
    }

    return sorted(
        _deduplicar_textos_preservando_ordem(valores),
        key=lambda valor: (ordem.get(valor, 999), valor.casefold()),
    )


def _normalizar_filtros_clientes_para_backend(filtros):
    saida = {}

    for nome, meta in DEFINICOES_FILTROS_CLIENTES.items():
        valor = filtros.get(nome)

        if meta["multiplo"]:
            saida[nome] = [
                str(x).strip()
                for x in (valor or [])
                if str(x or "").strip()
            ]
        else:
            saida[nome] = str(valor or "").strip()

    saida["q"] = str(filtros.get("q") or "").strip()
    saida["cliente"] = str(filtros.get("cliente") or "todos").strip().lower()

    if saida["cliente"] not in {"todos", "1", "0"}:
        saida["cliente"] = "todos"

    return saida


def _serializar_para_chave_cache(valor) -> str:
    return json.dumps(valor, sort_keys=True, ensure_ascii=False, default=str, separators=(",", ":"))


def _gerar_chave_cache_clientes(prefixo: str, payload: dict) -> str:
    texto = _serializar_para_chave_cache(payload)
    hash_texto = hashlib.sha256(texto.encode("utf-8")).hexdigest()
    return f"clientes:{prefixo}:{hash_texto}"


def _aplicar_filtros_clientes(query, filtros, excluir=None):
    excluir = set(excluir or [])
    filtros = _normalizar_filtros_clientes_para_backend(filtros)

    cls = DimClassificacacaoClientes
    rec = DimRecorrencia
    pub = DimPublicoAlvo

    if "q" not in excluir and filtros["q"]:
        q_texto = str(filtros["q"] or "").strip()
        q_digitos = re.sub(r"\D+", "", q_texto)
        condicoes_busca = []

        """
        Eu separo busca numérica de busca textual para reduzir varredura.
        - Número curto: tenta IDEmpresa direto.
        - Número maior: tenta CNPJ por prefixo.
        - Texto: prioriza prefixo; mantém contains somente com 4+ letras para não matar o índice em buscas curtas.
        """
        if q_digitos:
            if len(q_digitos) <= 9:
                try:
                    condicoes_busca.append(DimEmpresas.IDEmpresa == int(q_digitos))
                except Exception:
                    pass

            if len(q_digitos) >= 3:
                condicoes_busca.append(cast(DimEmpresas.CNPJ, String).like(f"{q_digitos}%"))

            if len(q_digitos) >= 8:
                condicoes_busca.append(cast(DimEmpresas.CNPJ, String).like(f"%{q_digitos}%"))
        else:
            like_prefixo = f"{q_texto}%"
            condicoes_busca.extend([
                DimEmpresas.RazaoSocial.like(like_prefixo),
                DimEmpresas.NomeFantasia.like(like_prefixo),
                DimEmpresas.Municipio.like(like_prefixo),
                DimEmpresas.UF.like(like_prefixo),
                DimEmpresas.Porte.like(like_prefixo),
                DimCnaes.Setor.like(like_prefixo),
                DimCnaes.Classe.like(like_prefixo),
                DimCnaes.SubClasse.like(like_prefixo),
                DimCnaes.ClassificacaoMacro.like(like_prefixo),
                DimEmpresaProprietaria.RazaoSocial.like(like_prefixo),
                cls.ClusterGrupoCliente.like(like_prefixo),
                cls.ClassificacaoPerfilEmpresa.like(like_prefixo),
                cls.ClasseValor.like(like_prefixo),
                cls.TipoEscalaOperacional.like(like_prefixo),
                cls.ClasseEstrutural.like(like_prefixo),
                cls.ClasseGeo.like(like_prefixo),
                rec.ClasseFrequencia.like(like_prefixo),
                rec.ClasseRecencia.like(like_prefixo),
                pub.NomePerfil.like(like_prefixo),
                pub.TipoUsoTerritorio.like(like_prefixo),
            ])

            if len(q_texto) >= 4:
                like_contem = f"%{q_texto}%"
                condicoes_busca.extend([
                    DimEmpresas.RazaoSocial.like(like_contem),
                    DimEmpresas.NomeFantasia.like(like_contem),
                    DimEmpresas.Municipio.like(like_contem),
                    DimCnaes.Setor.like(like_contem),
                    DimCnaes.Classe.like(like_contem),
                    DimCnaes.SubClasse.like(like_contem),
                    DimCnaes.ClassificacaoMacro.like(like_contem),
                ])

        if condicoes_busca:
            query = query.filter(or_(*condicoes_busca))

    for nome, meta in DEFINICOES_FILTROS_CLIENTES.items():
        if nome in excluir:
            continue

        coluna = meta["coluna"]
        valor = filtros.get(nome)

        if meta["multiplo"]:
            if valor:
                query = query.filter(coluna.in_(valor))
        else:
            if valor:
                query = query.filter(coluna == valor)

    if "cliente" not in excluir:
        if filtros["cliente"] == "1":
            query = query.filter(func.coalesce(DimEmpresas.BitCliente, 0) == 1)
        elif filtros["cliente"] == "0":
            query = query.filter(func.coalesce(DimEmpresas.BitCliente, 0) == 0)

    return query



















def _so_digitos(v: str) -> str:
    if not v:
        return ""
    return (
        str(v)
        .replace(".", "")
        .replace("-", "")
        .replace("/", "")
        .replace(" ", "")
        .strip()
    )


def _paginacao_basica(page: int, per_page: int, total: int):
    """Cria objeto simples de paginação igual o padrão do seu template."""
    if per_page <= 0:
        per_page = 20

    total_pages = max((total + per_page - 1) // per_page, 1)
    page = max(min(page, total_pages), 1)

    inicio = (page - 1) * per_page + 1 if total > 0 else 0
    fim = min(page * per_page, total) if total > 0 else 0

    return {
        "page": page,
        "per_page": per_page,
        "total": total,
        "total_pages": total_pages,
        "inicio": inicio,
        "fim": fim,
        "has_prev": page > 1,
        "has_next": page < total_pages,
        "prev_page": page - 1 if page > 1 else 1,
        "next_page": page + 1 if page < total_pages else total_pages,
    }


def _filtro_anti_lixo_clientes():
    return (
        (DimEmpresas.CNPJ.isnot(None))
        & (DimEmpresas.CNPJ != "")
        & (DimEmpresas.CNPJ != "00000000000000")
        & (DimEmpresas.CNPJ != "99999999999999")
        & (DimEmpresas.RazaoSocial.isnot(None))
        & (DimEmpresas.RazaoSocial != "")
        & (DimEmpresas.RazaoSocial != "None")
        & (DimEmpresas.UF.isnot(None))
        & (DimEmpresas.UF != "")
        & (DimEmpresas.Municipio.isnot(None))
        & (DimEmpresas.Municipio != "")
    )


def _aplicar_from_clientes(query):
    cls = DimClassificacacaoClientes
    rec = DimRecorrencia
    pub = DimPublicoAlvo

    return (
        query
        .select_from(DimEmpresas)
        .outerjoin(DimCnaes, DimCnaes.cnaepadrao == DimEmpresas.CNAE)
        .outerjoin(
            DimEmpresaProprietaria,
            DimEmpresaProprietaria.IDEmpresaProprietaria == DimEmpresas.IDEmpresaProprietaria,
        )
        .outerjoin(cls, cls.IDEmpresa == DimEmpresas.IDEmpresa)
        .outerjoin(
            rec,
            (rec.IDEmpresa == DimEmpresas.IDEmpresa)
            & (
                (rec.IDEmpresaProprietaria.is_(None))
                | (rec.IDEmpresaProprietaria == DimEmpresas.IDEmpresaProprietaria)
            ),
        )
        .outerjoin(pub, pub.IDDimPublicoAlvo == cls.IDDimPublicoAlvo)
        .filter(_filtro_anti_lixo_clientes())
    )


def _query_clientes_base_ids():
    return _aplicar_from_clientes(
        db.session.query(DimEmpresas.IDEmpresa.label("IDDimClientesEuromidia"))
    )


